-- French (frFR): the guide forever/class/rogue/the-eye-of-bhossca (forever/class/rogue/the-eye-of-bhossca.guide).
-- Written by `forge i18n guides sync frFR`, which keeps every translation (docs/TRANSLATING.md, "Guide texts").
-- Translate the right-hand sides; "" shows the English. Keep each {kind:id} as it is: the game shows its
-- name there in French (the English is listed above the line). A name the English has in the plural, as words,
-- may be written with the singular's token from its "plural, as words" line: "Bandidos ({npc:251918})", "{npc:251918} ×8".
-- A token marked "no name in this language" would show in English: write that name in French words instead.
-- The comments are rewritten by sync.
return {
	-- Guide
	-- {item:277246} Ruby-Adorned Blade · {area:796} Scarlet Monastery
	["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "{item:277246}, le paiement de C pour une mission en solo dans le {area:796}.",

	-- Step 1: C's dead drop
	["C's dead drop"] = "La boîte aux lettres de C",
	-- {object:410369} Dead Drop · {area:204} Pyrewood Village · {area:236} Shadowfang Keep
	["C's next job comes by letter: once you are level 30 and have done the horn job, visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "",

	-- Step 2: The Scarlet Monastery
	-- {area:796} Scarlet Monastery
	["The {area:796}"] = "Le {area:796}",
	-- {zone:1420} Tirisfal Glades · {spell:427592} Scarlet Initiate's Uniform · {spell:921} Pick Pocket · {npc:4293} Scarlet Scryer · {item:210963} Scryer's Key · {item:210968} Reliquary Key
	["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {spell:427592} from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "Le monastère se dresse tout au nord-est des {zone:1420}. Entrez seul, hors de tout groupe. Avant d'entrer, prenez l'{spell:427592} dans le casier de fournitures des écuries derrière le monastère et portez-le ; le camouflage et les actes suspects le retirent, remettez-le donc après chaque changement d'aile. Au Cimetière, dans la salle de l'Expiation (la première grande salle), utilisez {spell:921} sur un {npc:4293} ou un Crieur écarlate pour obtenir la {item:210963}. À la Bibliothèque, ouvrez avec elle la boîte aux lettres personnelle de l'Athenaeum et lisez le message confidentiel. Il vous renvoie vous asseoir sur les deux bancs entre les deux statues du Cimetière. Surveillez les messages du mécanisme, puis prenez la {item:210968} dans le coffre de pierre : un élite se tient près du coffre avec une patrouille derrière lui, mais depuis le côté du mausolée nord vous pouvez tourner la caméra jusqu'à voir la boîte et cliquer dessus à travers le mur (une touche d'interaction fonctionne aussi). Un fantôme élite marche près du mausolée ; le morceau cassé à son bord vous tient hors de son chemin. Retournez ensuite à la Bibliothèque pour le reliquaire verrouillé et l'œil. Évitez de vous battre à travers l'instance.",
	["Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings."] = "Itinéraire en solo : clé au Cimetière, lettre à la Bibliothèque, bancs et coffre au Cimetière, puis reliquaire de la Bibliothèque pour l'œil. Lisez la lettre avant l'énigme des bancs ; vérifiez le déguisement à chaque changement d'aile.",

	-- Step 3: Back to the dead drop
	["Back to the dead drop"] = "Retour à la boîte aux lettres",
	-- {object:410369} Dead Drop
	["Place the eye in the {object:410369} near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared."] = "Déposez l'œil dans la {object:410369} près de Bois-du-Bûcher. Vérifiez une boîte aux lettres de capitale pour la lettre de paiement de C lors de votre prochaine visite prévue en ville, puis revenez ici pour la quête de récompense. Le paiement peut ne pas être disponible tout de suite ; ne refaites pas l'infiltration simplement parce que la récompense n'est pas encore apparue.",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Find the Eye of Bhossca inside the {area:796}."] = "Trouvez l'Œil de Bhossca dans le {area:796}.",
	-- ["Place the eye in the {object:410369} near Pyrewood. C's payment is the second Eye of Bhossca quest at the same chest."] = "Déposez l'œil dans {object:410369}, près de Bois-du-Bûcher. Le paiement de C est la seconde quête « L'Œil de Bhossca », au même coffre.",
	-- ["The monastery stands in the far north-east of {zone:1420}. Go in alone; C advises a disguise from the monastery's grounds before you enter."] = "Le monastère se dresse à l'extrême nord-est de {zone:1420}. Entrez seul ; C conseille de prendre un déguisement aux abords du monastère avant d'entrer.",
	-- ["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. After the horn job and C's next letter, check it for the new job. The data lists a minimum of 25, but beta players report receiving the invitation at 30 after the horn job and a city visit; this is not a guaranteed mail level. If no new note is offered, continue leveling and check after C writes."] = "La {object:410369} est un coffre près du {area:204}, dans le sud de la forêt des Pins-Argentés, juste au sud du {area:236}. Après le travail du cor et la lettre suivante de C, vérifiez-la pour le nouveau travail. Les données indiquent un minimum de 25, mais des joueurs de la bêta disent avoir reçu l'invitation au niveau 30 après le travail du cor et une visite en ville ; ce niveau de courrier n'est pas garanti. Si aucun nouveau message n'est proposé, continuez à monter de niveau et revenez voir après la lettre de C.",
	-- ["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. C's next note waits there once you are 25."] = "{object:410369} est un coffre près de {area:204}, dans le sud de la Forêt des Pins argentés (Silverpine Forest), juste au sud du {area:236}. La note suivante de C vous y attend une fois au niveau 25.",
}
